changeSet.sql:
CREATE TABLE model_token_budget_day (
    budget_day date PRIMARY KEY,
    charged_tokens bigint NOT NULL CHECK (charged_tokens >= 0)
);
CREATE TABLE model_token_reservation (
    id uuid PRIMARY KEY,
    budget_day date NOT NULL REFERENCES model_token_budget_day(budget_day),
    reserved_tokens bigint NOT NULL CHECK (reserved_tokens > 0),
    actual_tokens bigint CHECK (actual_tokens >= 0 AND actual_tokens <= reserved_tokens),
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX model_token_reservation_day_idx ON model_token_reservation(budget_day);
